from pathlib import Path
import json
import argparse
parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path);args=parser.parse_args()
p=Path(__file__).resolve().parents[1];d=(args.output or p/'dist').resolve();d.mkdir(parents=True,exist_ok=True);s=(p/'r45-source/Current.js').read_text()
s=s.replace('function readImage(source,radius,now,predictedVelocity=null){','function readImage(source,radius,now,predictedVelocity=null){\n const audit={now,predictedVelocity:predictedVelocity?{...predictedVelocity}:null,matches:[],dropped:0,costMs:0};')
s=s.replace('if(same)return prior.analysis;','if(same){window.r50audit={now,cacheHit:true,priorTimestamp:prior.timestamp,capture:{...window.r4capture},matches:[],costMs:0};return prior.analysis;}')
s=s.replace('const prior=imageState;', 'const prior=imageState;audit.priorTimestamp=prior?.timestamp??null;')
s=s.replace('return {x,y,r,npc,stalled,blocked:', '''if(npc){const ta=performance.now();if(audit.matches.length<256){audit.matches.push({objectIndex:used.size,previousIndex:match?previous.indexOf(match):null,error:match?error:null,x,y,r,previousVelocity:match?{x:match.vx,y:match.vy}:null,rawDisplacement:match?{x:(x-match.x)/dt,y:(y-match.y)/dt}:null,preClamp:match?{x:(match.vx||0)*.65+((x-match.x)/dt+(measuredCamera?.x??camera.x))*.35,y:(match.vy||0)*.65+((y-match.y)/dt+(measuredCamera?.y??camera.y))*.35}:null});}else audit.dropped++;audit.costMs+=performance.now()-ta;}return {x,y,r,npc,stalled,blocked:''')
s=s.replace('const analysis={objects,map,velocity};','''const ta=performance.now();Object.assign(audit,{cacheHit:false,dt,capture:{...window.r4capture},measuredCamera:measuredCamera?{...measuredCamera}:null,camera:{...camera},npcCamera:{...(measuredCamera??camera)},branch:measuredCamera?'food-measured':'camera-fallback',shiftCount:shifts.length});audit.costMs+=performance.now()-ta;window.r50audit=audit;const analysis={objects,map,velocity};''')
# order in output list is not used.size; store coordinates/radius as observation identity, not fabricated persistent IDs
s=s.replace('objectIndex:used.size,','')
(d/'Telemetry.js').write_text(s.replace('makeCurrent','makeTelemetry'));(p/'r50/Telemetry.js').write_text(s.replace('makeCurrent','makeTelemetry'))
html='''<!doctype html><title>r50 telemetry parity</title><h1>r50 fixed continuous75 plus duplicate75</h1><button id="run">Run fixed telemetry comparison</button><button id="save" disabled>Save comparison</button><pre id="status">Ready</pre><canvas id="source" style="width:2000px;height:1163px"></canvas><script src="Current.js"></script><script src="Telemetry.js"></script><script>
let result;run.onclick=async()=>{run.disabled=true;const c=document.getElementById('source'),ctx=c.getContext('2d'),a=makeCurrent(),b=makeTelemetry(),rows=[];try{for(const f of await(await fetch('frames.json')).json()){const im=new Image();im.src='frames/'+f.file;await im.decode();c.width=im.width;c.height=im.height;ctx.drawImage(im,0,0);for(let duplicate=0;duplicate<2;duplicate++){const now=f.at+duplicate*.1,t0=performance.now(),x=a.readImage(c,f.r,now,{x:0,y:0}),t1=performance.now(),y=b.readImage(c,f.r,now,{x:0,y:0}),t2=performance.now();const pa=a.plan(x.objects,f.r,x.map,200,x.velocity,{x:1,y:0},true),pb=b.plan(y.objects,f.r,y.map,200,y.velocity,{x:1,y:0},true);rows.push({file:f.file,duplicate,equal:JSON.stringify(x)===JSON.stringify(y),planEqual:JSON.stringify(pa)===JSON.stringify(pb),baselineMs:t1-t0,telemetryMs:t2-t1,audit:JSON.parse(JSON.stringify(window.r50audit))});}status.textContent='Processed '+rows.length+'/150';await new Promise(r=>setTimeout(r,10));}result={version:'r50',rows,summary:{count:rows.length,equal:rows.filter(r=>r.equal).length,planEqual:rows.filter(r=>r.planEqual).length,cacheHits:rows.filter(r=>r.audit.cacheHit).length,dropped:rows.reduce((a,r)=>a+(r.audit.dropped||0),0)}};document.getElementById('status').textContent=JSON.stringify(result.summary);}catch(e){result={error:String(e),rows};document.getElementById('status').textContent=String(e);}save.disabled=false;};save.onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(result)]));a.download='r50-parity.json';a.click()};</script>'''
(d/'r50.html').write_text(html);(p/'r50/fixture.html').write_text(html)
(p/'r50/plan.json').write_text(json.dumps({'hypothesis':'Bounded telemetry preserves perception and planning while exposing actual camera/matching inputs','fixed':'75 continuous source frames plus75 exact duplicate cache calls','caps':{'NPCperFrame':256,'liveRows':800,'games':1},'pass':'150/150 perception+plan equality;75cache hits;no cap drops;timing descriptive not winrate','liveStop':'150game seconds/210wallseconds/3stale decisions/800rows; preserve failures'},indent=2))
